test("選んだ兄弟の一員を運んで離すと、全員ぶんの置き直しが 1 回で届き、全員が同じ量だけずれる", () => {
  const onRepositionNodes = vi.fn();
  renderCanvas({ selection: setupSelection(["a", "b"]), onRepositionNodes });
  drawnSiblings();

  // 囲む矩形は 170〜250・95〜151 へ動き、どの辺・中心線からも 6px より離れている
  dragNode("a", { x: 30, y: 11 });

  expect(onRepositionNodes.mock.calls).toEqual([
    [[inHome("a", 130, 35), inHome("b", 70, 71)]],
  ]);
});

test("運んでいる途中でドキュメントの一員の座標が変わると、離したときはその時点の座標から運んだ量だけずれる", () => {
  // 掴んだ時点の座標（b は 40）を持ち続けると、b は 70 へ書かれる
  const onRepositionNodes = vi.fn();
  const { rerenderWith } = renderCanvas({
    selection: setupSelection(["a", "b"]),
    onRepositionNodes,
  });
  drawnSiblings();
  carryNode("a", { x: 30, y: 11 });

  rerenderWith(
    selectionFromArtboards(
      [
        {
          name: "home",
          width: 360,
          height: 240,
          children: [
            absoluteText("a", 100, 24),
            absoluteText("b", 50, 60),
            absoluteText("marker", 250, 0),
            { name: "flowing", type: "Text", props: { content: "流" } },
          ],
        },
        { name: "settings", width: 360, height: 240, children: [] },
      ],
      ["a", "b"],
    ),
  );
  drawnSiblings();
  dropOnto(drawn("a"), { x: 30, y: 11 });

  expect(onRepositionNodes.mock.calls).toEqual([
    [[inHome("a", 130, 35), inHome("b", 80, 71)]],
  ]);
});

test("運んでいる途中で一員が別の親へ移ると、離しても置き直しもツリー内の移動も届かない", () => {
  // 一員が同じ親の兄弟でなくなったら、押した一員だけをツリーへ移す運び方へは切り替えない
  const onRepositionNodes = vi.fn();
  const onMoveNode = vi.fn();
  const { rerenderWith } = renderCanvas({
    selection: setupSelection(["a", "b"]),
    onRepositionNodes,
    onMoveNode,
  });
  drawnSiblings();
  carryNode("a", { x: 30, y: 11 });

  rerenderWith(
    selectionFromArtboards(
      [
        {
          name: "home",
          width: 360,
          height: 240,
          children: [
            absoluteText("a", 100, 24),
            absoluteText("marker", 250, 0),
            { name: "flowing", type: "Text", props: { content: "流" } },
          ],
        },
        {
          name: "settings",
          width: 360,
          height: 240,
          children: [absoluteText("b", 40, 60)],
        },
      ],
      ["a", "b"],
    ),
  );
  drawnSiblings();
  dropOnto(drawn("settings"), { x: 30, y: 11 });

  expect([
    onRepositionNodes.mock.calls.length,
    onMoveNode.mock.calls.length,
  ]).toEqual([0, 0]);
});

test("選んだ兄弟の一員を運んでいる間、全員が運んだ分だけずれて見える", () => {
  renderCanvas({ selection: setupSelection(["a", "b"]) });
  drawnSiblings();

  carryNode("a", { x: 30, y: 11 });

  const styles = injectedStyles();
  expect([
    styles.includes(previewRule("a", { x: 30, y: 11 })),
    styles.includes(previewRule("b", { x: 30, y: 11 })),
  ]).toEqual([true, true]);
});

test("押した一員の辺は何にも近くなくても、囲む矩形の左辺が親の左辺に近ければ全員が寄る", () => {
  const onRepositionNodes = vi.fn();
  renderCanvas({ selection: setupSelection(["a", "b"]), onRepositionNodes });
  drawnSiblings();

  /*
   * 囲む矩形の左辺（`b` の左辺）が 97 — `home` の左辺の 3px 手前。押した `a` は 157〜177 で、
   * `a` だけを見ると寄らず a は 57、b は -3 になる
   */
  dragNode("a", { x: -43, y: 11 });

  expect(onRepositionNodes).toHaveBeenCalledWith([
    inHome("a", 60, 35),
    inHome("b", 0, 71),
  ]);
});

test("囲む矩形が揃え先に吸い付いている間、ガイド線は囲む矩形と揃え先をまたぐ長さで出る", () => {
  renderCanvas({ selection: setupSelection(["a", "b"]) });
  drawnSiblings();

  // 囲む矩形の右辺が 347 — `marker` の左辺（350）の 3px 手前
  carryNode("a", { x: 127, y: 11 });

  /*
   * 線は `marker` の上辺（60）から、囲む矩形の下辺（`b` の下辺 151）までをまたぐ。`a` だけを
   * 見ると下端は `a` の下辺 107 になる
   */
  expect(snapGuides()[0].getAttribute("style")).toContain(
    "left: 349px; top: 60px; width: 2px; height: 91px",
  );
});

test("まとめて運んでいる一員どうしは、互いの揃え先にならない", () => {
  const onRepositionNodes = vi.fn();
  renderCanvas({ selection: setupSelection(["a", "b"]), onRepositionNodes });
  drawnSiblings();

  /*
   * 囲む矩形の左辺 144 は、動く前の `b` の左辺（140）の 4px 先。`b` が揃え先に残っていると
   * 140 へ寄って動かなくなる
   */
  dragNode("a", { x: 4, y: 11 });

  expect(onRepositionNodes).toHaveBeenCalledWith([
    inHome("a", 104, 35),
    inHome("b", 44, 71),
  ]);
});

test("Alt を押しながらまとめて運んでいる間、距離は囲む矩形から測る", () => {
  renderCanvas({ selection: setupSelection(["a", "b"]) });
  drawnSiblings();

  /*
   * 囲む矩形 170〜250・95〜151 から `home` の辺まで、左 70・右 210・上 35・下 149。
   * `a` だけを見ると左 130・下 193 になる
   */
  carryNode("a", { x: 30, y: 11 }, "alt");

  expect(sortedFacingDistanceLabels()).toEqual(["149", "210", "35", "70"]);
});

test("別の artboard の上へまとめて運んで離すと、全員の行き先がその artboard になる", () => {
  const onRepositionNodes = vi.fn();
  renderCanvas({ selection: setupSelection(["a", "b"]), onRepositionNodes });
  drawnSiblings();

  dragNodeOnto("a", drawn("settings"), { x: 30, y: 30 });

  expect(
    onRepositionNodes.mock.lastCall?.[0].map(
      (edit: { edit: RepositionEdit }) => edit.edit.to.parentName,
    ),
  ).toEqual(["settings", "settings"]);
});

test("90 度回った Box の中の兄弟を回っていない artboard へまとめて運ぶと、一員ごとに中心を保つ座標と 90 度が書かれる", () => {
  /*
   * `frame` の座標の原点は `home` の座標で (250, 0)。運んだ量 (-20, 0) は親の座標で (0, 20)。
   * `chip`（10, 30 へ）は中心 (20, 36) を回して原点を足し、(204, 14)。`peg`（150, 80 へ）は
   * 中心 (160, 86) から同じく (154, 154)
   */
  const onRepositionNodes = vi.fn();
  renderCanvas({
    selection: DocumentSelection.fromNames(turnedFrameDocument(90), [
      "chip",
      "peg",
    ]),
    onRepositionNodes,
  });
  drawnTurnedFrame();

  dragNodeOnto("chip", drawn("home"), { x: -20, y: 0 });

  expect(onRepositionNodes).toHaveBeenCalledWith([
    {
      name: "chip",
      edit: RepositionEdit.rotatedTo(
        { parentName: "home", placement: { mode: "absolute", x: 204, y: 14 } },
        90,
      ),
    },
    {
      name: "peg",
      edit: RepositionEdit.rotatedTo(
        {
          parentName: "home",
          placement: { mode: "absolute", x: 154, y: 154 },
        },
        90,
      ),
    },
  ]);
});

test("⌘ を押しながらまとめて運ぶと、囲む矩形が親の辺に近くても寄らない", () => {
  const onRepositionNodes = vi.fn();
  renderCanvas({ selection: setupSelection(["a", "b"]), onRepositionNodes });
  drawnSiblings();

  dragNode("a", { x: -43, y: 11 }, "meta");

  expect(onRepositionNodes).toHaveBeenCalledWith([
    inHome("a", 57, 35),
    inHome("b", -3, 71),
  ]);
});

test("フローのノードが混ざった複数選択で一員を運ぶと、押した一員だけの置き直しが届く", () => {
  const onRepositionNodes = vi.fn();
  renderCanvas({
    selection: setupSelection(["a", "flowing"]),
    onRepositionNodes,
  });
  drawnSiblings();

  dragNode("a", { x: 30, y: 11 });

  expect(onRepositionNodes).toHaveBeenCalledWith([inHome("a", 130, 35)]);
});

test("選択をツリーと逆の順に組んでいても、届く置き直しはツリー順に並ぶ", () => {
  const onRepositionNodes = vi.fn();
  renderCanvas({ selection: setupSelection(["b", "a"]), onRepositionNodes });
  drawnSiblings();

  dragNode("a", { x: 30, y: 11 });

  expect(onRepositionNodes).toHaveBeenCalledWith([
    inHome("a", 130, 35),
    inHome("b", 70, 71),
  ]);
});

test("絶対配置の兄弟を選んだまま一員を押すと、押した時点では 2 つとも選ばれたまま", async () => {
  await renderUngrouped();

  pressPointer(drawn("a"), { x: 100, y: 100 });

  expect(currentRowNames(tree())).toEqual(["a", "b"]);
});

test("一員を運んで離すと、2 つとも同じ量だけ動いて描かれる", async () => {
  await renderUngrouped();

  drag(drawn("a"), { from: { x: 100, y: 100 }, to: { x: 70, y: 112 } });

  expect([drawnPosition("a"), drawnPosition("b")]).toEqual([
    ["10px", "36px"],
    ["70px", "72px"],
  ]);
});

test("一員を運んで離しても、2 つとも選ばれたまま", async () => {
  await renderUngrouped();

  drag(drawn("a"), { from: { x: 100, y: 100 }, to: { x: 70, y: 112 } });
  // 離した直後の click は飲み込まれる。漏れれば `a` 1 つの選択になる
  fireEvent.click(drawn("a"));

  expect(currentRowNames(tree())).toEqual(["a", "b"]);
});

test("まとめて運んだあと ⌘Z を 1 回押すと、2 つとも元の位置に戻る", async () => {
  await renderUngrouped();
  drag(drawn("a"), { from: { x: 100, y: 100 }, to: { x: 70, y: 112 } });
  // 押した一員だけを運ぶ経路でも `b` は元の位置に描かれるので、取り消す前に動いたことを見る
  const movedB = drawnPosition("b");

  await userEvent.keyboard("{Meta>}z{/Meta}");

  expect([movedB, drawnPosition("a"), drawnPosition("b")]).toEqual([
    ["70px", "72px"],
    ["40px", "24px"],
    ["100px", "60px"],
  ]);
});

test("一員の中の Text を押して運ばずに離すと、続く click でその一員 1 つが選ばれる", async () => {
  await renderUngrouped();

  pressPointer(drawn("a-label"), { x: 100, y: 100 });
  releasePointer(drawn("a-label"), { x: 100, y: 100 });
  // `userEvent.click` は自前の `pointerdown` で掴み直すので、`click` だけを撃つ
  fireEvent.click(drawn("a-label"));

  expect(currentRowNames(tree())).toEqual(["a"]);
});

test("別の artboard の上へまとめて運ぶと、2 つとも元の並び順のままその artboard の子になる", async () => {
  await renderUngrouped();

  // 離すのを運んだ先へ撃つのは、運んでいるノードが当たり判定から外れるため
  pressPointer(drawn("a"), { x: 100, y: 100 });
  movePointer(drawn("settings"), { x: 70, y: 112 });
  releasePointer(drawn("settings"), { x: 70, y: 112 });

  expect(drawnChildNames("settings")).toEqual(["a", "b"]);
});

test("まとめて運んでいる途中で編集画面の外へ出て取り消すと、どちらも動かず 2 つとも選ばれたまま", async () => {
  await renderUngrouped();

  pressPointer(drawn("a"), { x: 100, y: 100 });
  movePointer(drawn("settings"), { x: 70, y: 112 });
  leavePointer(drawn("settings"));

  expect([
    drawnPosition("a"),
    drawnPosition("b"),
    currentRowNames(tree()),
  ]).toEqual([
    ["40px", "24px"],
    ["100px", "60px"],
    ["a", "b"],
  ]);
});

test("フローの子が混ざった複数選択では、一員を押した時点でその一員 1 つが選ばれる", async () => {
  await renderUngrouped(true);

  pressPointer(drawn("a"), { x: 100, y: 100 });

  expect(currentRowNames(tree())).toEqual(["a"]);
});

test("フローの子が混ざった複数選択で一員を運ぶと、その一員だけが動く", async () => {
  await renderUngrouped(true);

  drag(drawn("a"), { from: { x: 100, y: 100 }, to: { x: 70, y: 112 } });

  expect([drawnPosition("a"), drawnPosition("b")]).toEqual([
    ["10px", "36px"],
    ["100px", "60px"],
  ]);
});

test("小数の座標の一員と整数の一員をまとめて運ぶと、一員ごとに丸めた座標とそこから逆算したずらし量になる", () => {
  const dropped = SiblingsRepositionTarget.create(
    {
      ...GrabbedInHome,
      members: [
        {
          ...GrabbedInHome.members[0],
          placement: { mode: "absolute", x: 10.5, y: 0 },
        },
        {
          ...GrabbedInHome.members[1],
          placement: { mode: "absolute", x: 40, y: 0 },
        },
      ],
    },
    { x: 30, y: 0 },
    Home,
  );

  expect(
    dropped.members.map((member) => [
      member.target.placement.x,
      member.target.offset.x,
    ]),
  ).toEqual([
    [41, 30.5],
    [70, 30],
  ]);
});

test("小数の座標の一員と整数の一員をまとめて運んでいる間は、一員ごとに別々のずらし量で見せる", () => {
  const preview = SiblingsRepositionTarget.preview(
    SiblingsRepositionTarget.create(
      {
        ...GrabbedInHome,
        members: [
          {
            ...GrabbedInHome.members[0],
            placement: { mode: "absolute", x: 10.5, y: 0 },
          },
          {
            ...GrabbedInHome.members[1],
            placement: { mode: "absolute", x: 40, y: 0 },
          },
        ],
      },
      { x: 30, y: 0 },
      Home,
    ),
  );

  expect(preview.members).toEqual([
    { name: "a", offset: { x: 30.5, y: 0 } },
    { name: "b", offset: { x: 30, y: 0 } },
  ]);
});

test("落とし先の親が決まっていない間も、小数の座標の一員と整数の一員は一員ごとに別々のずらし量で見せる", () => {
  const preview = SiblingsRepositionTarget.carriedPreview(
    {
      parentName: "home",
      parentRotation: 0,
      members: [
        { name: "a", placement: { mode: "absolute", x: 10.5, y: 0 } },
        { name: "b", placement: { mode: "absolute", x: 40, y: 0 } },
      ],
    },
    { x: 30, y: 0 },
  );

  expect(preview.members).toEqual([
    { name: "a", offset: { x: 30.5, y: 0 } },
    { name: "b", offset: { x: 30, y: 0 } },
  ]);
});

test("入れ子の一員の内側を押しても、全員をまとめて運ぶ", () => {
  const carried = carriedNamesAt(
    ["a", "b"],
    UnderPointer.create(OnALabel, SelectionDigs.NoDeeper),
  );

  expect(carried).toEqual(Option.some(["a", "b"]));
});

test("ロック中の一員がいると、まとめて運ばない", () => {
  const carried = carriedNamesAt(
    ["b", "sealed"],
    UnderPointer.create(OnB, SelectionDigs.NoDeeper),
  );

  expect(Option.isSome(carried)).toBe(false);
});

test("非表示の一員がいると、まとめて運ばない", () => {
  const carried = carriedNamesAt(
    ["b", "ghost"],
    UnderPointer.create(OnB, SelectionDigs.NoDeeper),
  );

  expect(Option.isSome(carried)).toBe(false);
});

test("親の違うノードが混ざっていると、まとめて運ばない", () => {
  const carried = carriedNamesAt(
    ["b", "stray"],
    UnderPointer.create(OnB, SelectionDigs.NoDeeper),
  );

  expect(Option.isSome(carried)).toBe(false);
});

test("⌘ で一員の中の子を押すと、まとめて運ばない", () => {
  const carried = carriedNamesAt(
    ["a", "b"],
    UnderPointer.create(OnALabel, SelectionDigs.Deepest),
  );

  expect(Option.isSome(carried)).toBe(false);
});

test("⌘ で押した位置のいちばん内側が一員そのものなら、全員をまとめて運ぶ", () => {
  const carried = carriedNamesAt(
    ["a", "b"],
    UnderPointer.create(OnB, SelectionDigs.Deepest),
  );

  expect(carried).toEqual(Option.some(["a", "b"]));
});

test("複数選択中に入れ子の一員を押すと、その一員を選ぶ", () => {
  const name = DocumentSelection.nameToSelectAt(
    DocumentSelection.fromNames(setupSelection().document, ["label", "login"]),
    UnderPointer.create(["label", "card", "home"], SelectionDigs.NoDeeper),
  );

  expect(name).toEqual(Option.some("label"));
