test("祖先と子孫の両方が選ばれて両方が候補に載るとき、掘らない指定では子孫が選ばれる", () => {
  const name = SelectionDig.nameAt(SelectionDigs.NoDeeper, Candidates, [
    "outer-panel",
    "inner-panel",
  ]);

  expect(Option.unwrap(name)).toBe("inner-panel");
});

test("同じ親の絶対配置の兄弟を逆順に渡しても、親と各自の座標がツリー順に返る", () => {
  expect(Option.unwrap(siblingsOf(["b", "a"]))).toEqual({
    parentName: "home",
    members: [
      { name: "a", placement: { mode: "absolute", x: 10, y: 20 } },
      { name: "b", placement: { mode: "absolute", x: 30, y: 40 } },
    ],
  });
});

test("1 件でも受け入れられない置き直しがあれば、先頭が通る指定でも全体が失敗になる", () => {
  const result = DesignDocument.repositionAll(setupDocument(), [
    { name: "a", edit: placedAt("panel", 0, 0) },
    { name: "b", edit: placedAt("title", 0, 0) },
  ]);

  expect(result).toEqual(
    Result.err({ kind: "parent-not-found", name: "title" }),
  );
});

test("2 つをまとめて置き直したあと 1 回戻すと、2 つとも元の座標に戻る", () => {
  const repositioned = Option.unwrap(
    EditorState.repositionAll(stateWithAbsoluteSiblings(), [
      { name: "badge", edit: toHome(70, 12) },
      { name: "chip", edit: toHome(130, 48) },
    ]),
  );

  const undone = Option.unwrap(EditorState.undo(repositioned));

  expect([propsOf(undone, "badge"), propsOf(undone, "chip")]).toEqual([
    expect.objectContaining({ x: 40, y: 24 }),
    expect.objectContaining({ x: 100, y: 60 }),
  ]);
});

test("まとめて置き直しても、選択は変わらない", () => {
  const selected = EditorState.selectNodes(stateWithAbsoluteSiblings(), [
    "badge",
    "chip",
  ]);

  const repositioned = Option.unwrap(
    EditorState.repositionAll(selected, [
      { name: "badge", edit: toHome(70, 12) },
      { name: "chip", edit: toHome(130, 48) },
    ]),
  );

  expect(
    DocumentSelection.names(EditorState.documentSelection(repositioned)),
  ).toEqual(["badge", "chip"]);
});

test("置き直したあと 1 回戻すと縦横とも元の座標に戻る", () => {
  const repositioned = Option.unwrap(
    repositionOne(stateWithAbsoluteSiblings(), "badge", toHome(70, 12)),
  );

  const undone = Option.unwrap(EditorState.undo(repositioned));

  expect(propsOf(undone, "badge")).toMatchObject({ x: 40, y: 24 });
});

test("まとめて運んだ兄弟を離したときは、直後のクリックを飲み込む", () => {
  // 押した時点の選択（全員）を保つので、離した位置の click で選び直させない
  const dragging = NodeDrag.moveTo(
    NodeDrag.grab({ dragged: CarryingSiblings, origin: { x: 100, y: 100 } }),
    { x: 100, y: 140 },
    Carrying.droppable(
      DropEdit.reposition(SampleSiblingsTarget, SampleRepositionLines),
    ),
  );

  expect(NodeDrag.consumesClick(NodeDrag.release(dragging))).toBe(true);
});

release(drag: NodeDrag): NodeDrag {
  if (drag.kind !== "dragging") {
    return NodeDrag.create();
  }
  switch (drag.grab.dragged.kind) {
    case "existing":
    case "selected-siblings":
      return { kind: "dropped" };
    case "new":
      return NodeDrag.create();
  }
},

type GrabbedSiblingsOf<M extends SiblingPlacement> = Readonly<{
  /** 一員すべての今の親の名前。 */
  parentName: string;
  parentRotation: Angle;
  /** 一員それぞれ。ツリー順。 */
  members: NonEmptyArray<M>;
}>;

/** 掴んだ時点の兄弟の座標と、今の親の向き（`GrabbedPlacement` の全員ぶん）。 */
export type GrabbedSiblings = GrabbedSiblingsOf<SiblingPlacement>;

/** まとめて運ぶ一員の、掴んだ時点の座標と自分の向きと形。 */
export type GrabbedMemberGeometry = SiblingPlacement & OwnGeometry;

/** 掴んだ時点の兄弟に、一員ごとの自分の向きと形を足したもの（`GrabbedGeometry` の全員ぶん）。 */
export type GrabbedSiblingsGeometry = GrabbedSiblingsOf<GrabbedMemberGeometry>;

carriedSiblingsAt(
  selection: DocumentSelection,
  underPointer: UnderPointer,
): Option<TwoOrMoreArray<string>> {
  const selected = selection.selected;
  if (selected.kind !== "multiple") {
    return Option.none;
  }

  const document = selection.document;
  const grabbed = DocumentSelection.nodeNameAt(selection, underPointer);
  const grabsMember =
    Option.isSome(grabbed) && selected.names.includes(grabbed.value);
  if (!grabsMember) {
    return Option.none;
  }

  const isUncarriable = (name: string) =>
    DesignDocument.isLocked(document, name) ||
    DesignDocument.isHidden(document, name);
  if (selected.names.some(isUncarriable)) {
    return Option.none;
  }

  return Option.map(
    DesignDocument.findSiblingPlacements(document, selected.names),
    () => selected.names,
  );
},

function carryingAt(context: DropContext): Carrying {
  const dragged = context.grab.dragged;
  switch (dragged.kind) {
    case "new":
      return intoTreeCarrying(context, dragged);
    case "existing": {
      const placed = DesignDocument.findSiblingPlacements(context.document, [
        dragged.name,
      ]);
      return Option.isSome(placed)
        ? repositionCarrying(context, placed.value)
        : intoTreeCarrying(context, dragged);
    }
    case "selected-siblings": {
      const placed = DesignDocument.findSiblingPlacements(
        context.document,
        dragged.names,
      );
      return Option.isSome(placed)
        ? repositionCarrying(context, placed.value)
        : Carrying.nothing();
    }
  }
}

create(
  grabbed: GrabbedSiblingsGeometry,
  carried: Offset,
  dropParent: DropParentCoordinates,
): SiblingsRepositionTarget {
  return {
    parentName: grabbed.parentName,
    dropParentName: dropParent.name,
    members: ArrayEx.mapNonEmpty(grabbed.members, (member) => ({
      name: member.name,
      target: RepositionTarget.create(
        grabbedMember(grabbed, member),
        carried,
        dropParent,
      ),
    })),
  };
},

/**
 * 離したときにドキュメントへ届ける、全員ぶんの置き直し。
 *
 * @param target 全員の行き先
 * @returns 一員ごとの、落とし先の親と座標（向きを書き換えるならその向き）。ツリー順
 */
toEdits(target: SiblingsRepositionTarget): NonEmptyArray<NodeRepositionEdit> {
  return ArrayEx.mapNonEmpty(target.members, (member) => {
    const to = ChildPlacement.create(
      target.dropParentName,
      member.target.placement,
    );

    const rotation = member.target.rotation;
    return {
      name: member.name,
      edit: Option.isSome(rotation)
        ? RepositionEdit.rotatedTo(to, rotation.value)
        : RepositionEdit.create(to),
    };
  });
},
